CREATE TABLE `worker_commands` (`id` VARCHAR(191) NOT NULL, `job_id` VARCHAR(191) NOT NULL, `worker_id` VARCHAR(191) NOT NULL, `command_type` ENUM('FOCUS_PAYMENT_PAGE','MARK_PAYMENT_COMPLETED','MARK_PAYMENT_FAILED','CLEANUP_JOB_SESSION') NOT NULL, `status` ENUM('PENDING','CLAIMED','COMPLETED','FAILED','EXPIRED') NOT NULL DEFAULT 'PENDING', `error_code` VARCHAR(191) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `acknowledged_at` DATETIME(3) NULL, `completed_at` DATETIME(3) NULL, `expires_at` DATETIME(3) NOT NULL, INDEX `worker_commands_worker_id_status_expires_at_idx`(`worker_id`,`status`,`expires_at`), PRIMARY KEY (`id`));
ALTER TABLE `worker_commands` ADD CONSTRAINT `worker_commands_job_id_fkey` FOREIGN KEY (`job_id`) REFERENCES `automation_jobs`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `worker_commands` ADD CONSTRAINT `worker_commands_worker_id_fkey` FOREIGN KEY (`worker_id`) REFERENCES `automation_workers`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
